head.script:
scwin.onpageload = function() {
	wdc_main.createWindow("TEST1", null, "WindowContainer_MapChart_WESE-739_(WSQ-5581)_component3.xml", "TEST1", "TEST1");
	wdc_main.createWindow("TEST2", null, "WindowContainer_MapChart_WESE-739_(WSQ-5581)_component4.xml", "TEST2", "TEST2");
};

	scwin.checkVal = function() {
		return document.getElementsByTagName('svg').length == 1;
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wdc_main_nameLayer_'+$p.id+'wdc_main_subWindow1').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wdc_main_nameLayer_'+$p.id+'wdc_main_subWindow0').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wdc_main_nameLayer_'+$p.id+'wdc_main_subWindow1').click()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wdc_main_nameLayer_'+$p.id+'wdc_main_subWindow0').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
